<?php
require_once dirname(__DIR__,2).'/includes/bootstrap.php';require_once ROOT_PATH.'/includes/cost_analysis.php';require_login();require_permission('costs.view');$pdo=db();$range=cost_date_range($_GET);$search=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$limit=20;$offset=($page-1)*$limit;$where=$search!==''?"WHERE v.plate_number ILIKE ? OR v.brand ILIKE ? OR v.model ILIKE ? OR v.type ILIKE ?":'';$params=[];if($search!==''){$like='%'.$search.'%';$params=[$like,$like,$like,$like];}$count=$pdo->prepare("SELECT COUNT(*) FROM vehicles v $where");$count->execute($params);$total=(int)$count->fetchColumn();$source=cost_sources_sql();$sql="WITH costs AS ($source),a AS(SELECT vehicle_id,SUM(amount) total,SUM(amount) FILTER(WHERE category='Fuel') fuel,SUM(amount) FILTER(WHERE category='Maintenance') maintenance,SUM(amount) FILTER(WHERE category='Toll') other FROM costs WHERE occurred_at>=?::date AND occurred_at<?::date GROUP BY vehicle_id),t AS(SELECT vehicle_id,COUNT(*) trips FROM trips WHERE status='Completed' AND actual_arrival>=?::date AND actual_arrival<?::date GROUP BY vehicle_id) SELECT v.plate_number,v.type,TRIM(v.brand||' '||v.model) vehicle,COALESCE(t.trips,0) trips,COALESCE(a.fuel,0) fuel,COALESCE(a.maintenance,0) maintenance,COALESCE(a.other,0) other,COALESCE(a.total,0) total FROM vehicles v LEFT JOIN a ON a.vehicle_id=v.id LEFT JOIN t ON t.vehicle_id=v.id $where ORDER BY total DESC,v.plate_number LIMIT $limit OFFSET $offset";$q=$pdo->prepare($sql);$q->execute(array_merge([$range['start'],$range['end'],$range['start'],$range['end']],$params));$rows=$q->fetchAll();$pages=max(1,(int)ceil($total/$limit));$active_page='cost-by-vehicle';$body_class=trim(($body_class??'').' cost-analysis-module cost-by-vehicle-page');$page_title='Cost by Vehicle';require ROOT_PATH.'/includes/header.php';?>
<div class="d-flex flex-wrap justify-content-between align-items-end mb-4 gap-3 cost-page-heading"><div><h1 class="mb-1">Cost by Vehicle</h1><p class="text-muted-custom mb-0">Costs linked to Fleet Management vehicles.</p></div><form method="get" class="d-flex flex-wrap align-items-end gap-2 cost-filter-form"><div><label class="tc-form-label small">Search</label><input class="tc-form-control" name="q" value="<?=e($search)?>" placeholder="Plate, model or type"></div><div><label class="tc-form-label small">From</label><input class="tc-form-control" type="date" name="from" value="<?=e($range['from'])?>"></div><div><label class="tc-form-label small">To</label><input class="tc-form-control" type="date" name="to" value="<?=e($range['to'])?>"></div><button class="tc-btn tc-btn-primary">Apply</button></form></div><div class="tc-card"><div class="tc-table-container border-0"><table class="tc-table"><thead><tr><th>Vehicle</th><th>Type</th><th>Trips</th><th>Fuel</th><th>Maintenance</th><th>Other</th><th>Total</th><th>Average / trip</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="text-center text-muted-custom py-4">No vehicles match the selected filters.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['plate_number'])?></strong><div class="small text-muted-custom"><?=e($r['vehicle'])?></div></td><td><?=e($r['type'])?></td><td><?=(int)$r['trips']?></td><td><?=money($r['fuel'])?></td><td><?=money($r['maintenance'])?></td><td><?=money($r['other'])?></td><td class="fw-bold"><?=money($r['total'])?></td><td><?=money((int)$r['trips']?(float)$r['total']/(int)$r['trips']:0)?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php if($pages>1):?><nav class="mt-3"><ul class="pagination justify-content-end"><?php for($i=1;$i<=$pages;$i++):?><li class="page-item <?=$i===$page?'active':''?>"><a class="page-link" href="?<?=http_build_query(['q'=>$search,'from'=>$range['from'],'to'=>$range['to'],'page'=>$i])?>"><?=$i?></a></li><?php endfor;?></ul></nav><?php endif;?><script src="<?=BASE_URL?>/js/cost-analysis.js?v=<?=(int)filemtime(ROOT_PATH.'/js/cost-analysis.js')?>"></script><?php require ROOT_PATH.'/includes/footer.php';?>
